import React, { useEffect, useState } from "react";
import "../components/style.css";
import SiteHeader from "../components/SiteHeader";
import SiteFooter from "../components/SiteFooter";
import { useAuth } from "../context/AuthContext";

export default function History() {
  const { token } = useAuth();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");

  useEffect(() => {
    if (!token) {
      setErr("Нужно войти в систему, чтобы видеть историю оценок.");
      setLoading(false);
      return;
    }

    (async () => {
      try {
        const resp = await fetch("/api/evaluations", {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await resp.json();
        if (!resp.ok) throw new Error(data?.message || "Ошибка загрузки истории");
        setItems(Array.isArray(data) ? data : data.value || []);
      } catch (e) {
        setErr(e.message);
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  if (loading) {
    return (
      <div className="page-shell">
        <SiteHeader actionLabel="На главную" actionTo="/" />
        <main className="container narrow">
          <section className="glass-panel">Загрузка...</section>
        </main>
        <SiteFooter />
      </div>
    );
  }

  if (err) {
    return (
      <div className="page-shell">
        <SiteHeader actionLabel="На главную" actionTo="/" />
        <main className="container narrow">
          <section className="glass-panel form-error">{err}</section>
        </main>
        <SiteFooter />
      </div>
    );
  }

  return (
    <div className="page-shell">
      <SiteHeader actionLabel="На главную" actionTo="/" />
      <main className="container wide">
        <section className="glass-panel">
          <p className="eyebrow">Личный кабинет</p>
          <h1 className="post-title">История оценок</h1>

          {items.length === 0 ? (
            <p className="hero-description">Пока нет сохранённых оценок.</p>
          ) : (
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>
                    <th style={th}>Дата</th>
                    <th style={th}>Параметры</th>
                    <th style={th}>Цена</th>
                    <th style={th}>Цена за м²</th>
                  </tr>
                </thead>
                <tbody>
                  {items.map((x) => (
                    <tr key={x._id || `${x.createdAt}-${x.predicted_price}`}>
                      <td style={td}>{new Date(x.createdAt).toLocaleString()}</td>
                      <td style={td}>
                        {x.input?.area} м², {x.input?.rooms} комн, этаж {x.input?.floor}/{x.input?.total_floors}
                      </td>
                      <td style={td}>{Math.round(x.predicted_price).toLocaleString()} ₸</td>
                      <td style={td}>{Math.round(x.price_per_m2).toLocaleString()} ₸</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </main>
      <SiteFooter />
    </div>
  );
}

const th = { textAlign: "left", borderBottom: "1px solid #ddd", padding: "10px 8px" };
const td = { borderBottom: "1px solid #eee", padding: "10px 8px", verticalAlign: "top" };
